/**
 * pdf-unified-export.test.ts - Milestone M2C: Shared Pagination PDF Integration Tests
 * Governing Context: AKHAR-ARCH-PAG — Milestone M2C
 *
 * Verifies:
 * 1. PDF export consumes the exact PaginationResult generated by the unified layout engine.
 * 2. Zero independent Chromium pagination: renders discrete physical .page-sheet elements.
 * 3. US Letter (8.5x11 in) and ISO A4 (210x297 mm) physical sheet geometry and standard margins.
 * 4. 18.0pt strict line-box baseline pitch across all screenplay elements.
 * 5. Running headers: suppressed on page 1, displayed on page 2+.
 * 6. Dialogue continuations: (MORE) and (CONT'D) presentation for contdSetting 'on' vs 'off'.
 * 7. 100% parity between Editor pagination decisions and PDF exporter decisions on identical fixtures.
 * 8. Font validation: verifies production Noto Sans Gurmukhi and explicitly rejects corrupt/mismatched fonts.
 * 9. Zero canonical document or database mutation: presentation-only labels.
 * 10. Backward compatibility: legacy PDF export continues to work when useUnifiedPagination is false/omitted.
 */

import { describe, it, expect } from 'vitest';
import fs from 'fs';
import path from 'path';
import {
  generateScreenplayHtml,
  generateUnifiedScreenplayPdfHtml,
  validateExportFonts,
} from '../src/core/export/pdfExporter';
import { createPaginationEngine } from '../src/core/layout/paginationEngine';
import { draftToLayoutBlocks } from '../src/core/layout/paginationAdapter';
import { createTextLayoutService } from '../src/core/layout/textLayoutService';
import { FontMetricsProvider } from '../src/core/layout/fontMetrics';
import { ScriptDraft, TitleMetadata, ScreenplayBlock } from '../src/types/screenplay';

describe('Milestone M2C: Shared Pagination PDF Integration', () => {
  const fontPath = path.resolve(process.cwd(), 'public/fonts/NotoSansGurmukhi.ttf');
  const gurmukhiFontBase64 = fs.existsSync(fontPath) ? fs.readFileSync(fontPath).toString('base64') : '';
  const courierPath = path.resolve(process.cwd(), 'public/fonts/CourierPrime.ttf');
  const courierFontBase64 = fs.existsSync(courierPath) ? fs.readFileSync(courierPath).toString('base64') : '';

  const sampleMetadata: TitleMetadata = {
    title: 'ਅੰਮ੍ਰਿਤਸਰ ਦੀ ਕਹਾਣੀ',
    author: 'ਗੁਰਪ੍ਰੀਤ ਸਿੰਘ',
    basedOn: 'ਅਸਲ ਘਟਨਾਵਾਂ ਤੇ ਆਧਾਰਿਤ',
    rights: 'Copyright 2026',
    contact: 'gurpreet@example.com',
  };

  const createTestDraft = (blocks: ScreenplayBlock[], id = 'd_m2c', name = 'M2C Master Draft'): ScriptDraft => ({
    id,
    name,
    isMain: true,
    createdAt: '2026-11-05T00:00:00.000Z',
    modifiedAt: '2026-11-05T00:00:00.000Z',
    blocks,
  });

  const defaultHeadlessOptions = {
    allowHeadlessFallback: true,
  };

  // ---------------------------------------------------------------------------
  // 1. Discrete Physical PDF Sheets & Geometry
  // ---------------------------------------------------------------------------
  describe('1. Discrete Physical PDF Sheets & Geometry', () => {
    it('generates exact Letter .page-sheet containers with 8.5in x 11in geometry and 1.5in left margin', () => {
      const blocks: ScreenplayBlock[] = [
        { id: 'sh1', type: 'scene_heading', text: 'EXT. GOLDEN TEMPLE - DAY' },
        { id: 'act1', type: 'action', text: 'ਪਵਿੱਤਰ ਸਰੋਵਰ ਦਾ ਪਾਣੀ ਸੂਰਜ ਦੀ ਰੌਸ਼ਨੀ ਵਿੱਚ ਚਮਕ ਰਿਹਾ ਹੈ।' },
      ];
      const draft = createTestDraft(blocks);

      const html = generateUnifiedScreenplayPdfHtml(draft, sampleMetadata, {
        paperSize: 'letter',
        includeTitlePage: false,
        courierFontBase64,
        gurmukhiFontBase64,
        ...defaultHeadlessOptions,
      });

      expect(html).toContain('@page {');
      expect(html).toContain('size: 8.5in 11in;');
      expect(html).toContain('margin: 0;');
      expect(html).toContain('width: 8.5in;');
      expect(html).toContain('height: 11in;');
      expect(html).toContain('padding: 1.0in 1.0in 1.0in 1.5in;');
      expect(html).toContain('class="page-sheet screenplay-page-sheet" data-page-number="1"');
    });

    it('generates exact A4 .page-sheet containers with 210mm x 297mm geometry and 38.1mm left margin', () => {
      const blocks: ScreenplayBlock[] = [
        { id: 'sh1', type: 'scene_heading', text: 'EXT. VILLAGE ROAD - DAY' },
        { id: 'act1', type: 'action', text: 'ਇੱਕ ਪੁਰਾਣੀ ਬੱਸ ਕੱਚੇ ਰਾਹ ਉੱਤੇ ਧੂੜ ਉਡਾਉਂਦੀ ਜਾ ਰਹੀ ਹੈ।' },
      ];
      const draft = createTestDraft(blocks);

      const html = generateUnifiedScreenplayPdfHtml(draft, sampleMetadata, {
        paperSize: 'a4',
        includeTitlePage: false,
        courierFontBase64,
        gurmukhiFontBase64,
        ...defaultHeadlessOptions,
      });

      expect(html).toContain('@page {');
      expect(html).toContain('size: 210mm 297mm;');
      expect(html).toContain('margin: 0;');
      expect(html).toContain('width: 210mm;');
      expect(html).toContain('height: 297mm;');
      expect(html).toContain('padding: 25.4mm 25.4mm 25.4mm 38.1mm;');
      expect(html).toContain('class="page-sheet screenplay-page-sheet" data-page-number="1"');
    });

    it('enforces 18.0pt strict line-box baseline pitch on screenplay lines and slot spacers', () => {
      const blocks: ScreenplayBlock[] = [
        { id: 'sh1', type: 'scene_heading', text: 'INT. ROOM - NIGHT' },
        { id: 'ch1', type: 'character', text: 'ਰਾਜਵਿੰਦਰ' },
        { id: 'd1', type: 'dialogue', text: 'ਕੀ ਤੂੰ ਸੱਚ ਬੋਲ ਰਿਹਾ ਹੈਂ?' },
      ];
      const draft = createTestDraft(blocks);

      const html = generateUnifiedScreenplayPdfHtml(draft, sampleMetadata, {
        paperSize: 'letter',
        includeTitlePage: false,
        ...defaultHeadlessOptions,
      });

      expect(html).toContain('line-height: 18pt;');
      expect(html).toContain('.screenplay-line {');
      expect(html).toContain('height: 18pt;');
      expect(html).toContain('.slot-blank-line {');
      expect(html).toContain('height: 18pt;');
    });
  });

  // ---------------------------------------------------------------------------
  // 2. Running Headers & First-Page Suppression
  // ---------------------------------------------------------------------------
  describe('2. Running Headers & First-Page Suppression', () => {
    it('suppresses running header on page 1 and displays "2." on page 2 at 36pt top distance', () => {
      // 36 individual action blocks to cleanly fill page 1 (slots 0..35) and spill to page 2
      const blocks: ScreenplayBlock[] = Array.from({ length: 38 }, (_, i) => ({
        id: `act-${i}`,
        type: 'action',
        text: `Action line ${i + 1} ਪੰਜਾਬੀ ਸਕ੍ਰਿਪਟ ਲਾਈਨ।`,
      }));
      const draft = createTestDraft(blocks);

      const html = generateUnifiedScreenplayPdfHtml(draft, sampleMetadata, {
        paperSize: 'letter',
        includeTitlePage: false,
        ...defaultHeadlessOptions,
      });

      // Verify page 1 exists without header
      const page1Match = html.match(/<div class="page-sheet screenplay-page-sheet" data-page-number="1">([\s\S]*?)<\/div>\s*<div class="page-sheet/);
      expect(page1Match).not.toBeNull();
      expect(page1Match![1]).not.toContain('class="page-header"');

      // Verify page 2 exists with header "2."
      const page2Match = html.match(/<div class="page-sheet screenplay-page-sheet" data-page-number="2">([\s\S]*?)<\/div>\s*<\/body>/);
      expect(page2Match).not.toBeNull();
      expect(page2Match![1]).toContain('<div class="page-header">2.</div>');
    });
  });

  // ---------------------------------------------------------------------------
  // 3. Dialogue Continuation & ContdSetting
  // ---------------------------------------------------------------------------
  describe('3. Dialogue Continuation & ContdSetting (on vs off)', () => {
    const createSplittingDialogueDraft = (): ScriptDraft => {
      // 16 action blocks consume 31 slots (1st block = 1 slot, 15 blocks = 30 slots: 1 blank + 1 line)
      const actionBlocks: ScreenplayBlock[] = Array.from({ length: 16 }, (_, i) => ({
        id: `lead-act-${i}`,
        type: 'action',
        text: `Leading action line ${i + 1}.`,
      }));

      // Character cue consumes 1 blank + 1 cue = 2 slots (total 33 slots used)
      // Available slots on page 1: 36 - 33 = 3 slots
      // Dialogue needs minSplitBefore (2 lines) + MORE (1 slot) = exactly 3 slots on page 1!
      // Remaining lines split onto page 2!
      const charBlock: ScreenplayBlock = {
        id: 'char-pawan',
        type: 'character',
        text: 'ਪਵਨ',
      };
      const dialogueBlock: ScreenplayBlock = {
        id: 'dial-long',
        type: 'dialogue',
        text: 'ਇਹ ਪਹਿਲੀ ਲਾਈਨ ਹੈ।\nਇਹ ਦੂਜੀ ਲਾਈਨ ਹੈ ਜੋ ਪੰਨੇ ਦੇ ਹੇਠਲੇ ਹਿੱਸੇ ਤੇ ਰਹਿੰਦੀ ਹੈ।\nਇਹ ਤੀਜੀ ਲਾਈਨ ਹੈ।\nਇਹ ਚੌਥੀ ਲਾਈਨ ਹੈ ਜੋ ਦੂਜੇ ਪੰਨੇ ਤੇ ਜਾਂਦੀ ਹੈ।\nਇਹ ਪੰਜਵੀਂ ਲਾਈਨ ਹੈ।\nਇਹ ਛੇਵੀਂ ਲਾਈਨ ਹੈ।',
      };

      return createTestDraft([...actionBlocks, charBlock, dialogueBlock]);
    };

    it('renders (MORE) at page 1 bottom and ਪਵਨ (CONT\'D) at page 2 top when contdSetting="on"', () => {
      const draft = createSplittingDialogueDraft();

      const html = generateUnifiedScreenplayPdfHtml(draft, sampleMetadata, {
        paperSize: 'letter',
        includeTitlePage: false,
        contdSetting: 'on',
        ...defaultHeadlessOptions,
      });

      // Page 1 has (MORE)
      expect(html).toContain('class="slot-line screenplay-more-continuation select-none">(MORE)</div>');

      // Page 2 has ਪਵਨ (CONT'D)
      expect(html).toContain('class="slot-line character screenplay-contd-continuation">ਪਵਨ (CONT&#39;D)</div>');

      // Canonical text unchanged
      expect(draft.blocks.find((b) => b.id === 'char-pawan')?.text).toBe('ਪਵਨ');
      expect(draft.blocks.find((b) => b.id === 'dial-long')?.text).not.toContain('(MORE)');
      expect(draft.blocks.find((b) => b.id === 'dial-long')?.text).not.toContain('(CONT\'D)');
    });

    it('renders (MORE) at page 1 bottom but SUPPRESSES (CONT\'D) at page 2 top when contdSetting="off"', () => {
      const draft = createSplittingDialogueDraft();

      const html = generateUnifiedScreenplayPdfHtml(draft, sampleMetadata, {
        paperSize: 'letter',
        includeTitlePage: false,
        contdSetting: 'off',
        ...defaultHeadlessOptions,
      });

      // Page 1 has (MORE)
      expect(html).toContain('class="slot-line screenplay-more-continuation select-none">(MORE)</div>');

      // Page 2 DOM elements do NOT contain (CONT'D)
      expect(html).not.toContain('class="slot-line character screenplay-contd-continuation"');
      expect(html).not.toContain('(CONT&#39;D)');
      expect(html).not.toContain('(CONT\'D)');

      // Canonical text unchanged
      expect(draft.blocks.find((b) => b.id === 'char-pawan')?.text).toBe('ਪਵਨ');
      expect(draft.blocks.find((b) => b.id === 'dial-long')?.text).not.toContain('(MORE)');
    });

    it('produces identical page counts and identical slot allocations across contdSetting states', () => {
      const draft = createSplittingDialogueDraft();

      const engine = createPaginationEngine();
      const layoutBlocks = draftToLayoutBlocks(draft);
      const metrics = new FontMetricsProvider({ measureFn: (t) => t.length * 7.2 });
      const layoutService = createTextLayoutService(metrics);

      const resultOn = engine.paginate(layoutBlocks, {
        paperSize: 'letter',
        contdSetting: 'on',
        textLayoutService: layoutService,
      });
      const resultOff = engine.paginate(layoutBlocks, {
        paperSize: 'letter',
        contdSetting: 'off',
        textLayoutService: layoutService,
      });

      // Both paginate across exactly 2 pages
      expect(resultOn.totalPages).toBe(2);
      expect(resultOff.totalPages).toBe(2);

      // Block-to-page mappings are identical
      for (const [blockId, pagesOn] of resultOn.blockPageMap.entries()) {
        const pagesOff = resultOff.blockPageMap.get(blockId);
        expect(Array.from(pagesOn)).toEqual(Array.from(pagesOff || []));
      }

      // Splitting dialogue is assigned to [1, 2] in both
      expect(Array.from(resultOn.blockPageMap.get('dial-long')!)).toEqual([1, 2]);
      expect(Array.from(resultOff.blockPageMap.get('dial-long')!)).toEqual([1, 2]);
    });
  });

  // ---------------------------------------------------------------------------
  // 4. Editor vs PDF Exporter Parity & Agreement
  // ---------------------------------------------------------------------------
  describe('4. Editor vs PDF Exporter Parity & Agreement', () => {
    it('guarantees 100% agreement between Editor PaginationResult and Exported PDF pages', () => {
      const blocks: ScreenplayBlock[] = [
        { id: 'sh1', type: 'scene_heading', text: 'EXT. VILLAGE SQUARE - MORNING' },
        { id: 'act1', type: 'action', text: 'ਪਿੰਡ ਦੀ ਸੱਥ ਵਿੱਚ ਲੋਕ ਇਕੱਠੇ ਹੋ ਰਹੇ ਹਨ।' },
        { id: 'char1', type: 'character', text: 'ਹਰਨਾਮ ਸਿੰਘ' },
        { id: 'dial1', type: 'dialogue', text: 'ਸਾਨੂੰ ਅੱਜ ਹੀ ਫੈਸਲਾ ਕਰਨਾ ਪਵੇਗਾ।' },
        ...Array.from({ length: 32 }, (_, i) => ({
          id: `act-fill-${i}`,
          type: 'action' as const,
          text: `Action fill paragraph ${i + 1} with realistic screenplay content.`,
        })),
        { id: 'sh2', type: 'scene_heading', text: 'INT. HAVELI - NIGHT' },
        { id: 'act2', type: 'action', text: 'ਹਵੇਲੀ ਅੰਦਰ ਹਨੇਰਾ ਛਾਇਆ ਹੋਇਆ ਹੈ।' },
      ];
      const draft = createTestDraft(blocks);

      const engine = createPaginationEngine();
      const layoutBlocks = draftToLayoutBlocks(draft);
      const editorResult = engine.paginate(layoutBlocks, { paperSize: 'letter', contdSetting: 'on' });

      // Generate PDF HTML passing editor's PaginationResult
      const pdfHtml = generateUnifiedScreenplayPdfHtml(draft, sampleMetadata, {
        paperSize: 'letter',
        includeTitlePage: false,
        paginationResult: editorResult,
      });

      // 1. Total page count match
      const sheetMatches = pdfHtml.match(/class="page-sheet screenplay-page-sheet"/g);
      expect(sheetMatches?.length).toBe(editorResult.totalPages);

      // 2. Block-to-page allocation match
      for (const [blockId, pages] of editorResult.blockPageMap.entries()) {
        for (const pageNum of pages) {
          const pageRegex = new RegExp(
            `<div class="page-sheet screenplay-page-sheet" data-page-number="${pageNum}">([\\s\\S]*?)(?:<div class="page-sheet|<\\/body>)`
          );
          const match = pdfHtml.match(pageRegex);
          expect(match, `Page ${pageNum} container should exist in PDF HTML`).not.toBeNull();
          expect(match![1]).toContain(`id="${blockId}"`);
        }
      }

      // 3. Header number match
      for (let p = 2; p <= editorResult.totalPages; p++) {
        expect(pdfHtml).toContain(`<div class="page-header">${p}.</div>`);
      }
    });

    it('preserves mid-block split lines in correct sequence across sheets', () => {
      const blocks: ScreenplayBlock[] = [
        ...Array.from({ length: 16 }, (_, i) => ({
          id: `lead-${i}`,
          type: 'action' as const,
          text: `Padding line ${i + 1}`,
        })),
        { id: 'char-split', type: 'character', text: 'ਅਮਨ' },
        {
          id: 'dial-split',
          type: 'dialogue',
          text: 'ਪਹਿਲਾ ਵਾਕ ਪਹਿਲੇ ਪੰਨੇ ਤੇ ਆਉਂਦਾ ਹੈ।\nਦੂਜਾ ਵਾਕ ਵੀ ਪਹਿਲੇ ਪੰਨੇ ਤੇ ਆਉਂਦਾ ਹੈ।\nਤੀਜਾ ਵਾਕ ਦੂਜੇ ਪੰਨੇ ਤੇ ਚਲਾ ਜਾਂਦਾ ਹੈ।\nਚੌਥਾ ਵਾਕ ਦੂਜੇ ਪੰਨੇ ਤੇ ਖ਼ਤਮ ਹੁੰਦਾ ਹੈ।',
        },
      ];
      const draft = createTestDraft(blocks);

      const html = generateUnifiedScreenplayPdfHtml(draft, sampleMetadata, {
        paperSize: 'letter',
        includeTitlePage: false,
        contdSetting: 'on',
        ...defaultHeadlessOptions,
      });

      // Split dialogue ID exists on both sheet 1 and sheet 2
      const page1Match = html.match(/data-page-number="1">([\s\S]*?)<\/div>\s*<div class="page-sheet/);
      const page2Match = html.match(/data-page-number="2">([\s\S]*?)<\/div>\s*<\/body>/);

      expect(page1Match![1]).toContain('id="dial-split"');
      expect(page1Match![1]).toContain('ਪਹਿਲਾ ਵਾਕ ਪਹਿਲੇ ਪੰਨੇ ਤੇ ਆਉਂਦਾ ਹੈ।');
      expect(page1Match![1]).toContain('(MORE)');

      expect(page2Match![1]).toContain('ਅਮਨ (CONT&#39;D)');
      expect(page2Match![1]).toContain('id="dial-split"');
      expect(page2Match![1]).toContain('ਤੀਜਾ ਵਾਕ ਦੂਜੇ ਪੰਨੇ ਤੇ ਚਲਾ ਜਾਂਦਾ ਹੈ।');
    });
  });

  // ---------------------------------------------------------------------------
  // 5. Font Validation & Error Handling
  // ---------------------------------------------------------------------------
  describe('5. Font Validation & Explicit Error Handling', () => {
    it('validates production TrueType Noto Sans Gurmukhi font successfully', async () => {
      const result = await validateExportFonts({ gurmukhiFontBase64 });
      expect(result.valid).toBe(true);
    });

    it('rejects corrupt or invalid font buffer explicitly rather than silently falling back', async () => {
      const corruptBase64 = Buffer.from('NOT_A_TRUE_TYPE_FONT_HEADER').toString('base64');
      const result = await validateExportFonts({ gurmukhiFontBase64: corruptBase64 });
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
    });

    it('strictly prohibits silent uncertified font measurement fallback in headless environment', () => {
      const blocks: ScreenplayBlock[] = [{ id: 'b1', type: 'action', text: 'Action line' }];
      const draft = createTestDraft(blocks);

      // Without allowHeadlessFallback and without DOM Canvas 2D, must throw explicit error
      expect(() => {
        generateUnifiedScreenplayPdfHtml(draft, sampleMetadata, {
          paperSize: 'letter',
          includeTitlePage: false,
          allowHeadlessFallback: false,
        });
      }).toThrow(/Canvas 2D context is unavailable for certified font measurement/);
    });
  });

  // ---------------------------------------------------------------------------
  // 6. Title Page & Character Highlighting
  // ---------------------------------------------------------------------------
  describe('6. Title Page & Character Highlighting', () => {
    it('renders title page as discrete first .page-sheet when includeTitlePage=true', () => {
      const blocks: ScreenplayBlock[] = [{ id: 'b1', type: 'action', text: 'Action text' }];
      const draft = createTestDraft(blocks);

      const html = generateUnifiedScreenplayPdfHtml(draft, sampleMetadata, {
        paperSize: 'letter',
        includeTitlePage: true,
        ...defaultHeadlessOptions,
      });

      expect(html).toContain('class="page-sheet title-page" id="title-page"');
      expect(html).toContain('<h1 class="title-text">ਅੰਮ੍ਰਿਤਸਰ ਦੀ ਕਹਾਣੀ</h1>');
      expect(html).toContain('<p class="title-author">ਗੁਰਪ੍ਰੀਤ ਸਿੰਘ</p>');
      expect(html).toContain('class="page-sheet screenplay-page-sheet" data-page-number="1"');
    });

    it('omits title page sheet completely when includeTitlePage=false', () => {
      const blocks: ScreenplayBlock[] = [{ id: 'b1', type: 'action', text: 'Action text' }];
      const draft = createTestDraft(blocks);

      const html = generateUnifiedScreenplayPdfHtml(draft, sampleMetadata, {
        paperSize: 'letter',
        includeTitlePage: false,
        ...defaultHeadlessOptions,
      });

      expect(html).not.toContain('id="title-page"');
      expect(html).toContain('class="page-sheet screenplay-page-sheet" data-page-number="1"');
    });

    it('applies character highlighting in exported PDF HTML when character highlight setting is active', () => {
      const blocks: ScreenplayBlock[] = [
        { id: 'c1', type: 'character', text: 'ਪਵਨ' },
        { id: 'd1', type: 'dialogue', text: 'ਸਤਿ ਸ੍ਰੀ ਅਕਾਲ ਜੀ।' },
        { id: 'c2', type: 'character', text: 'ਹਰਮੀਤ' },
        { id: 'd2', type: 'dialogue', text: 'ਕਿਵੇਂ ਹੋ?' },
      ];
      const draft = createTestDraft(blocks);

      const html = generateUnifiedScreenplayPdfHtml(draft, sampleMetadata, {
        paperSize: 'letter',
        includeTitlePage: false,
        ...defaultHeadlessOptions,
        highlightCharacters: {
          enabled: true,
          selectedCharacters: ['ਪਵਨ'],
          color: 'rgba(255, 200, 0, 0.4)',
        },
      });

      // Pawan dialogue has character-highlight
      expect(html).toContain('class="character-highlight" style="background-color: rgba(255, 200, 0, 0.4)');
      expect(html).toContain('ਸਤਿ ਸ੍ਰੀ ਅਕਾਲ ਜੀ।</span>');

      // Harmeet is not highlighted
      expect(html).not.toContain('ਕਿਵੇਂ ਹੋ?</span>');
    });
  });

  // ---------------------------------------------------------------------------
  // 7. Backward Compatibility: Legacy Export Fallback
  // ---------------------------------------------------------------------------
  describe('7. Backward Compatibility: Legacy Export Fallback', () => {
    it('preserves legacy continuous body export when useUnifiedPagination is false or omitted', () => {
      const blocks: ScreenplayBlock[] = [
        { id: 'sh1', type: 'scene_heading', text: 'EXT. STREET - DAY' },
        { id: 'act1', type: 'action', text: 'Walking down the road.' },
      ];
      const draft = createTestDraft(blocks);

      const legacyHtml = generateScreenplayHtml(draft, sampleMetadata, {
        paperSize: 'letter',
        includeTitlePage: false,
        // useUnifiedPagination omitted
      });

      // Legacy format contains .screenplay-body and does NOT contain .page-sheet
      expect(legacyHtml).toContain('class="screenplay-body"');
      expect(legacyHtml).not.toContain('class="page-sheet"');
    });

    it('routes to unified discrete sheet generator when useUnifiedPagination=true', () => {
      const blocks: ScreenplayBlock[] = [
        { id: 'sh1', type: 'scene_heading', text: 'EXT. STREET - DAY' },
        { id: 'act1', type: 'action', text: 'Walking down the road.' },
      ];
      const draft = createTestDraft(blocks);

      const unifiedHtml = generateScreenplayHtml(draft, sampleMetadata, {
        paperSize: 'letter',
        includeTitlePage: false,
        useUnifiedPagination: true,
        ...defaultHeadlessOptions,
      });

      // Unified format contains discrete .page-sheet containers
      expect(unifiedHtml).toContain('class="page-sheet screenplay-page-sheet" data-page-number="1"');
      expect(unifiedHtml).not.toContain('class="screenplay-body"');
    });
  });
});
